"""Login HTTP: server-side session cookie and /api/me."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Request, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from endo_label.coordination import (
    Account,
    account_for_session,
    authenticate,
    create_session,
    db_path,
    delete_session,
)

SESSION_COOKIE = "session_id"

router = APIRouter()

_PUBLIC_API = frozenset({"/api/health", "/api/auth/login", "/api/auth/logout"})


class LoginBody(BaseModel):
    username: str
    password: str


def _me(account: Account) -> dict:
    return {
        "username": account.username,
        "roles": {
            "admin": account.admin,
            "reviewer": account.reviewer,
            "annotator": account.annotator,
        },
    }


def install_auth(app) -> None:
    @app.middleware("http")
    async def require_account(request: Request, call_next):
        path = request.url.path
        if (
            request.method == "OPTIONS"
            or not path.startswith("/api/")
            or path in _PUBLIC_API
        ):
            return await call_next(request)
        settings = request.app.state.settings
        token = request.cookies.get(SESSION_COOKIE)
        account = account_for_session(db_path(settings), token) if token else None
        if account is None or account.disabled:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        request.state.account = account
        return await call_next(request)


@router.post("/api/auth/login")
def login(body: LoginBody, response: Response, request: Request) -> dict:
    settings = request.app.state.settings
    path = db_path(settings)
    account = authenticate(path, body.username, body.password)
    if account is None:
        raise HTTPException(status_code=401, detail="Not authenticated")
    token = create_session(path, account.id)
    response.set_cookie(
        key=SESSION_COOKIE,
        value=token,
        httponly=True,
        samesite="lax",
        secure=settings.session_cookie_secure,
        path="/",
    )
    return _me(account)


@router.post("/api/auth/logout")
def logout(request: Request, response: Response) -> dict:
    token = request.cookies.get(SESSION_COOKIE)
    if token:
        delete_session(db_path(request.app.state.settings), token)
    response.delete_cookie(SESSION_COOKIE, path="/")
    return {"ok": True}


@router.get("/api/me")
def me(request: Request) -> dict:
    return _me(request.state.account)

"""Phase HTTP: exclusive label per Frame; optional span write."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from endo_label import catalog
from endo_label.config import Settings
from endo_label import labels_store


class PhaseSpanBody(BaseModel):
    phase: str | None = Field(...)
    from_frame: int = Field(..., ge=0, alias="from")
    to_frame: int = Field(..., ge=0, alias="to")

    model_config = {"populate_by_name": True}


class PhaseFrameBody(BaseModel):
    phase: str | None = None


def make_router(settings: Settings) -> APIRouter:
    router = APIRouter(tags=["phase"])

    def _meta(clip_id: str) -> dict:
        try:
            return catalog.clip_meta(settings, clip_id)
        except catalog.ClipNotFound:
            raise HTTPException(status_code=404, detail=f"Clip not found: {clip_id}") from None

    def _require_phase_name(name: str) -> None:
        phases = labels_store.load_vocab(settings).get("phases") or []
        if name not in phases:
            raise HTTPException(status_code=400, detail=f"unknown phase: {name}")

    @router.get("/api/phase/{clip_id}")
    def get_clip_phase(clip_id: str) -> dict:
        _meta(clip_id)
        return labels_store.load_clip(settings, "phase", clip_id)

    @router.put("/api/phase/{clip_id}/frames/{frame_index}")
    def put_frame_phase(clip_id: str, frame_index: int, body: PhaseFrameBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        if frame_index < 0 or frame_index >= n:
            raise HTTPException(status_code=404, detail=f"Frame index out of range: {frame_index}")
        doc = labels_store.load_clip(settings, "phase", clip_id)
        key = str(frame_index)
        if body.phase is None:
            doc["frames"].pop(key, None)
        else:
            _require_phase_name(body.phase)
            doc["frames"][key] = body.phase
        labels_store.save_clip(settings, "phase", clip_id, doc)
        return doc

    @router.post("/api/phase/{clip_id}/span")
    def paint_span(clip_id: str, body: PhaseSpanBody) -> dict:
        meta = _meta(clip_id)
        n = int(meta["frame_count"])
        a, b = body.from_frame, body.to_frame
        if a > b:
            a, b = b, a
        if a < 0 or b >= n:
            raise HTTPException(status_code=400, detail="span out of range")
        if body.phase is not None:
            _require_phase_name(body.phase)
        doc = labels_store.load_clip(settings, "phase", clip_id)
        for i in range(a, b + 1):
            key = str(i)
            if body.phase is None:
                doc["frames"].pop(key, None)
            else:
                doc["frames"][key] = body.phase
        labels_store.save_clip(settings, "phase", clip_id, doc)
        return doc

    return router

